---@class RoleCardFavorableGiftVo
local RoleCardFavorableGiftVo = Class("RoleCardFavorableGiftVo", SettingRefBase)

---__int
function RoleCardFavorableGiftVo:__init()
    self.roleId = nil              --角色ID（1001（角色编号）
    self.name = nil              --名称（角色名ID）
    self.gifts = nil              --好感度加成信息
end

---FillVo
---@param row TableML.TableFileRow
function RoleCardFavorableGiftVo:FillVo(row)
    base.FillVo(self,row)
    self.roleId = parse_number(row, "roleId")
    -- self.name = ParseUtils.ParseLocalizeText(row, "name")
    --self.gifts = base.ParseRewards(self, row, "likeGiftId", "love")

    local gifts = {}
    local idLists = parse_strings(parse_string(row, "likeGiftId"))
    local numsLists = parse_strings(parse_string(row, "love"))
    local len = math.min(#idLists, #numsLists)
    for i = 1, len do
        local id = checkNumber(idLists[i])
        if id > 0 then
            gifts[id] = {goodsId = id, goodsNum = checkNumber(numsLists[i])}
        end
    end
    self.gifts = gifts
end

function RoleCardFavorableGiftVo:__delete()
    self.roleId = nil
    self.name = nil
    self.gifts = nil
end

